import pymupdf,sys,re
for f in sys.argv[2:]:
    t=''.join(p.get_text() for p in pymupdf.open(f))
    open(f+'.txt','w').write(t)
    for m in re.finditer(sys.argv[1],t,re.I):
        s=max(0,m.start()-300); print('==',f,':',' '.join(t[s:m.end()+400].split())); print()
EOF
python3 -I ext.py 'solar wind|charge exchange|lifetime|ionization rate|photoioniz' dl/2512.22354.pdf dl/2601.15443.pdf | head -80",
